  // 无关时机连带调到这里，不能把那些时刻冒充成用户保存密钥的时刻。
  const tokenChanged = lsGet("llpub-token", "") !== token;
  const dskeyChanged = lsGet("llpub-dskey", "") !== dskey;
  lsSet("llpub-token", token);
  lsSet("llpub-dskey", dskey);
  idbSet("auth-keys", { token: token, dskey: dskey });
