// ─────────────────────────────────────────────────────────────
// 任务逻辑
// ─────────────────────────────────────────────────────────────
function bump(s) { if (s === S()) render(); else patchTabs(); }
function setTask(s, partial) { Object.assign(s.task, partial); bump(s); }
function stopTimers(s) {
  if (s.pollTimer !== null) { __llClearTimeout(s.pollTimer); s.pollTimer = null; }
  s.demoTimers.forEach(function (t) { __llClearTimeout(t); __llClearInterval(t); });
  s.demoTimers = [];
}

async function submitTask(wfId, body) {
  const res = await fetch(API_BASE + "/api/v1/comfyui/comfyui_workflow/" + encodeURIComponent(wfId), {
    method: "POST",
    headers: { Authorization: token, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    let detail = "";
    try {
      const j = await res.json();
      detail = String(j && (j.data && j.data.message || j.msg || j.message) || "");
    } catch { }
    throw new Error(detail ? "提交失败 HTTP " + res.status + "：" + detail : "提交失败 HTTP " + res.status);
  }
  return await res.json();
}

async function queryTask(taskId) {
  const res = await fetch(API_BASE + RESULT_PATH + taskId, { headers: { Authorization: token } });
  if (!res.ok) {
    let detail = "";
    try {
      const j = await res.json();
      detail = String(j && (j.data && j.data.message || j.msg || j.message) || "");
    } catch { }
    throw new Error(detail ? "查询失败 HTTP " + res.status + "：" + detail : "查询失败 HTTP " + res.status);
  }
  return await res.json();
}

function finishTask(s, videoUrl, prompt, meta) {
  stopTimers(s);
  setTask(s, { status: "success", progress: 100, message: "已完成", startedAt: s.task.startedAt });
  const item = {
    id: uid(), videoUrl: videoUrl, demo: false,
    poster: s.images.length ? s.images[0].url : undefined,
    prompt: prompt, meta: meta, time: Date.now(),
    status: videoUrl ? "ok" : "failed",
  };
  s.history.unshift(item);
  if (videoUrl) {
    s.view = { videoUrl: videoUrl, demo: false, poster: s.images.length ? s.images[0].url : undefined, prompt: prompt, meta: meta, time: Date.now() };
    cacheVideoBlob(item.id, videoUrl);
  }
  attachPosterThumb(s, item);
  persistState(s);
  bump(s);
}

function failTask(s, message, prompt, meta) {
  stopTimers(s);
  setTask(s, { status: "failed", message: message, startedAt: s.task.startedAt });
  const item = {
    id: uid(), demo: false,
    poster: s.images.length ? s.images[0].url : undefined,
    prompt: prompt, meta: meta, time: Date.now(), status: "failed", message: message,
  };
  s.history.unshift(item);
  attachPosterThumb(s, item);
  persistState(s);
  bump(s);
}

function startPolling(s, taskId, prompt, meta) {
  let attempts = 0;
  const loop = async function () {
    attempts += 1;
    if (attempts > POLL_MAX_ATTEMPTS) {
      failTask(s, "任务超时（约 1 小时），请稍后在历史中查看或重新生成", prompt, meta);
      return;
    }
    try {
      const resp = await queryTask(taskId);
      const status = String(resp.data && resp.data.status ? resp.data.status : "").toLowerCase();
      if (status === "success" || status === "completed" || status === "complete") {
        const results = (resp.data && resp.data.results) || [];
        const videoUrl = results.length && results[0] ? results[0].url : "";
        if (!videoUrl) {
          failTask(s, "任务状态已完成，但接口没有返回视频地址；请检查工作流结果字段或在服务端确认任务产物", prompt, meta);
          return;
        }
        finishTask(s, videoUrl, prompt, meta);
        return;
      }
      if (status === "failed" || status === "fail" || status === "error" || status === "cancelled") {
        failTask(s, (resp.data && resp.data.message) || resp.msg || "生成失败", prompt, meta);
        return;
      }
      const queued = status === "queued" || status === "pending";
      setTask(s, {
        status: "running",
        progress: Math.min(90, s.task.progress + (queued ? 3 : 5)),
        message: queued ? "排队中…" : "生成中…",
        startedAt: s.task.startedAt,
      });
      s.pollTimer = __llSetTimeout(loop, POLL_INTERVAL);
    } catch (err) {
      failTask(s, (err instanceof Error ? err.message : "查询任务失败") + "（若为网络/跨域问题，见页面底部提示）", prompt, meta);
    }
  };
  loop();
}

function demoRun(s, meta) {
  toast("演示模式：不出真视频，只走一遍流程。填自己的 Token 后才真实生成。");
  setTask(s, { status: "submitting", progress: 4, message: "演示模式 · 不出真视频 · 正在走流程…", startedAt: Date.now() });
  s.demoTimers.push(__llSetTimeout(function () {
    setTask(s, { status: "running", progress: 10, message: "演示模式 · 不出真视频 · 流程演示中…", startedAt: s.task.startedAt });
    const iv = __llSetInterval(function () {
      if (s.task.status !== "running") { __llClearInterval(iv); return; }
      const next = Math.min(98, s.task.progress + 2);
      setTask(s, { status: "running", progress: next, message: "演示模式 · 不出真视频 · 流程演示中…", startedAt: s.task.startedAt });
      if (next >= 98) {
        __llClearInterval(iv);
        s.demoTimers.push(__llSetTimeout(function () {
          stopTimers(s);
          setTask(s, { status: "success", progress: 100, message: "演示完成 · 未生成真实视频 · 填自己的 Token 后走真实 API", startedAt: s.task.startedAt });
          const demoItem = {
            id: uid(), demo: true,
            poster: s.images.length ? s.images[0].url : undefined,
            prompt: s.prompt.trim(), meta: meta, time: Date.now(), status: "ok",
          };
          s.history.unshift(demoItem);
          attachPosterThumb(s, demoItem);
          s.view = { demo: true, poster: s.images.length ? s.images[0].url : undefined, prompt: s.prompt.trim(), meta: meta, time: Date.now() };
          persistState(s);
          bump(s);
        }, 700));
      }
    }, 120);
  }, 900));
}

// ── 优化 v1：生成前校验（只拦能算清楚的错，不猜）──
// 拦：分镜缺号/跳号、分镜数超过该时长上限、<d> 标签不成对、
// 台词 <d> 前面没有 <Subject N> (Sx) 说话人。
// 不拦（没把握）：台词和中文原文是否一字不改、人物外观是否真像，
// 这些只能靠人看，校验函数不编造判断。
function maxShotsFor(duration) {
  if (duration <= 6) return 2;
  if (duration <= 10) return 3;
  return 5;
}
function validateBeforeGenerate(s) {
  const prompt = s.prompt.trim();
  if (!prompt) return "请先填写描述词";
  const wf = activeWorkflowProfile(s);
  if (wf.minImages > 0 && s.images.length < wf.minImages) return "请至少添加 1 张参考图";
  const boundNoImg = boundPromptGroups(s).find(function (g) {
    return !s.images.some(function (im) { return im.groupId === g.id; });
  });
  if (boundNoImg) return "已绑定到描述词的「" + boundNoImg.name + "」还没有参考图，请先给它绑定参考图或取消绑定";
  const shotNums = [];
  const reShot = /\[Shot\s+(\d+)\]/g;
  let m;
  while ((m = reShot.exec(prompt)) !== null) shotNums.push(parseInt(m[1], 10));
  if (shotNums.length > 0) {
    for (let i = 0; i < shotNums.length; i++) {
      if (shotNums[i] !== i + 1) return "分镜编号不连续：第 " + (i + 1) + " 个分镜是 [Shot " + shotNums[i] + "]，应为 [Shot " + (i + 1) + "]，请补齐或改号后再生成";
    }
    const max = maxShotsFor(s.duration);
    if (shotNums.length > max) return "分镜 " + shotNums.length + " 个，时长 " + s.duration + " 秒装不下（该时长最多 " + max + " 镜）。请把时长调到 " + (shotNums.length <= 3 ? "7–10 秒" : "11–15 秒") + "，或减少分镜后再生成";
  }
  const openD = (prompt.match(/<d>/g) || []).length;
  const closeD = (prompt.match(/<\/d>/g) || []).length;
  if (openD !== closeD) return "台词标签不成对：<d> 有 " + openD + " 个，</d> 有 " + closeD + " 个，请检查后再生成";
  if (openD > 0) {
    const parts = prompt.split("<d>");
    for (let i = 1; i < parts.length; i++) {
      const before = parts[i - 1].slice(-220);
      if (!/<Subject\s+\d+>\s*\(S\d+(,S\d+)*\)/.test(before)) {
        return "第 " + i + " 句台词前面没写说话人：台词前要写 <Subject N> (Sx) says, 再写 <d>，请补上后再生成";
      }
    }
    const subjNums = [];
    const reSubj = /<Subject\s+(\d+)>/g;
    while ((m = reSubj.exec(prompt)) !== null) subjNums.push(parseInt(m[1], 10));
    const uniq = Array.from(new Set(subjNums)).sort(function (a, b) { return a - b; });
    for (let i = 0; i < uniq.length; i++) {
      if (uniq[i] !== i + 1) return "人物编号不连续：用到了 <Subject " + uniq[i] + ">，但 <Subject " + (i + 1) + "> 没出现，请检查编号后再生成";
    }
  }
  return null;
}
function toggleHighlight(id) {
  const s = S();
  s.highlightGroup = (s.highlightGroup === id) ? null : id;
  render();
}
// 绑定连线 v4（v6.56 按 Gemini 规格重做）：严格左进右出——线从素材
// 卡（上游）右侧中点出、进组卡（下游）左侧中点；组卡右侧中点出、
// 进描述词卡左侧中点。去箭头、无 SVG 端点圆：线在卡片原生接口点
// （.uv-port-dot）下方干净收尾，方向靠渐变亮头认（源淡→目标亮）。
// 三档自适应贝塞尔（bezierPath）：缝小自动压平、几乎贴上画直线、
// 目标被拖到源头左边时柔和绕行，任何距离都不回环打结。拖动跟随：
// 按下时快照各卡实测尺寸（s.drag.sizes，口径与 edgeMeasure /
// tidyMeasure 一致、兜底值与现行调用点相同，图卡高随 P1 自适应高
// 实测、不写死），edgeMeasure 拖动中命中快照直接返回、零
// getBoundingClientRect；move 里经 scheduleDragSync 的 rAF 合并刷新
