      const gm = edgeMeasure(g.id, 300, 156);
      const active = s.highlightGroup === g.id || s.selectedId === g.id || s.hoverId === g.id || s.selectedId === "prompt" || s.hoverId === "prompt";
      const srcColor = g.color || (g.kind === "char" ? "#38bdf8" : "#a78bfa");
