  const z = s.cam.zoom || 1;
  const wx = (ev.clientX - d.rect.left - s.cam.x) / z;
  const wy = (ev.clientY - d.rect.top - s.cam.y) / z;
  const isAsset = s.images.some(function (x) { return x.id === id; }) || s.audios.some(function (x) { return x.id === id; });
