    for (let i = 0; i < s.groups.length; i++) {
      const g = s.groups[i];
      const m = (d.sizes && d.sizes[g.id]) || { w: 300, h: 156 };
      if (wx >= g.x && wx <= g.x + m.w && wy >= g.y && wy <= g.y + m.h) { d.dropTargetId = g.id; break; }
    }
