function generate() {
  const s = S();
  if (s.task.status === "running" || s.task.status === "submitting") return;
  const err = validateBeforeGenerate(s);
  if (err) { toast("生成前检查没通过：" + err); return; }
  if (s.images.some(function (im) { return !im.groupId; }) && /<Subject\s+\d+>/.test(s.prompt)) {
    toast("提醒：有参考图还没绑定角色/场景，继续生成可能串人，生成前最好先右键绑定");
  }
  stopTimers(s);

  const meta = s.resolution + " · " + s.duration + "s" + (s.seed.trim() ? " · 种子 " + s.seed.trim() : "");
  // v6.55：提交体走 assembleSubmission 拼装（无组绑定时与旧版逐字
  // 一致），再按当前工作流能力档案切片（默认 U24 是 9 图 3 音、
  // 时长上限 15s，不切任何东西）；提交地址按工作流动态拼。
  const wf = activeWorkflowProfile(s);
  const assembled = assembleSubmission(s);
  const body = { prompt: assembled.prompt };
  const sv = parseInt(s.seed, 10);
  if (!Number.isNaN(sv)) body.seed = sv;
  body.duration = Math.min(s.duration, wf.maxDur);
  body.resolution = s.resolution;
  assembled.images.slice(0, wf.maxImages).forEach(function (im, i) { body["ref_image_" + i] = im.url; });
  assembled.audios.slice(0, wf.maxAudios).forEach(function (a, i) { body["ref_audio_" + i] = a.url; });

  if (!token.trim()) { demoRun(s, meta); return; }

  setTask(s, { status: "submitting", progress: 6, message: "正在提交任务…", startedAt: Date.now() });
  submitTask(wf.id, body).then(function (resp) {
    const taskId = resp.data && resp.data.task_id;
    if (!taskId) {
      failTask(s, (resp.data && resp.data.message) || resp.msg || "未返回 task_id", assembled.prompt, meta);
      return;
    }
    setTask(s, { status: "running", progress: 8, message: "排队中…", startedAt: s.task.startedAt });
    startPolling(s, taskId, assembled.prompt, meta);
  }).catch(function (err) {
    failTask(s, (err instanceof Error ? err.message : "提交任务失败") + "（若为网络/跨域问题，见页面底部提示）", assembled.prompt, meta);
  });
}

function selectHistory(id) {
  const s = S();
  const item = s.history.find(function (h) { return h.id === id; });
  if (!item) return;
  const busy = s.task.status === "running" || s.task.status === "submitting";
  if (!busy) stopTimers(s);
  const show = function () {
    s.view = { videoUrl: item.videoUrl, localVideoUrl: item.localVideoUrl, demo: item.demo, poster: item.poster, prompt: item.prompt, meta: item.meta, time: item.time };
    if (busy) { bump(s); return; }
    setTask(s, { status: item.status === "ok" ? "success" : "failed", progress: item.status === "ok" ? 100 : 0, message: item.message || "", startedAt: item.time });
  };
  // v6.55：优先放 IndexedDB 里缓存的视频本体（远程链接会过期）；
  // 没缓存或读不到就用远程地址，行为与旧版一致。
  if (item.videoUrl && !item.localVideoUrl) {
    idbGet("video-blob-" + item.id).then(function (blob) {
      if (blob) { try { item.localVideoUrl = URL.createObjectURL(blob); } catch { } }
      show();
    });
    return;
  }
  show();
}

function closeView() {
  const s = S();
  const busy = s.task.status === "running" || s.task.status === "submitting";
  s.view = null;
  if (busy) { bump(s); return; }
  setTask(s, { status: "idle", progress: 0, message: "", startedAt: 0 });
}

function deleteHistoryItem(id) {
  const s = S();
  const item = s.history.find(function (h) { return h.id === id; });
  s.history = s.history.filter(function (h) { return h.id !== id; });
  if (item && s.view && s.view.time === item.time) s.view = null;
  s.menu = null;
  persistState(s);
  bump(s);
}

