function readFileAsDataUrl(file) {
  return new Promise(function (resolve, reject) {
    const fr = new FileReader();
    fr.onload = function () { resolve(String(fr.result)); };
    fr.onerror = function () { reject(new Error("读取文件失败")); };
    fr.readAsDataURL(file);
  });
}

async function handleFiles(files, kind) {
  if (!files || files.length === 0) return;
  const s = S();
  const beforeCount = s.images.length + s.audios.length;
  const list = Array.from(files);
  for (const file of list) {
    if (kind === "image" && s.images.length >= MAX_IMAGES) { toast("参考图最多 " + MAX_IMAGES + " 张"); break; }
    if (kind === "audio" && s.audios.length >= MAX_AUDIOS) { toast("参考音频最多 " + MAX_AUDIOS + " 段"); break; }
    try {
      const url = await readFileAsDataUrl(file);
      if (kind === "image") {
        const idx = s.images.length;
        s.images.push({ id: uid(), url: url, name: file.name, kind: "file", x: 430 + idx * 42, y: 120 + idx * 34 });
      } else {
        const idx = s.audios.length;
        s.audios.push({ id: uid(), url: url, name: file.name, kind: "file", x: 430 + idx * 42, y: 560 + idx * 96 });
      }
    } catch { }
  }
  if (s.images.length + s.audios.length !== beforeCount) invalidateTidySnap(s);
  persistAssets(s);
  render();
}

function addUrlAsset() {
  const s = S();
  const text = s.urlText.trim();
  if (!text) { toast("请先粘贴素材链接"); return; }
  let parsed;
  try { parsed = new URL(text); } catch { toast("链接格式不正确"); return; }
  if (parsed.protocol !== "https:" && parsed.protocol !== "http:") { toast("只支持 http / https 链接"); return; }
  if (s.urlKind === "image") {
    if (s.images.length >= MAX_IMAGES) { toast("参考图最多 " + MAX_IMAGES + " 张"); return; }
    const idx = s.images.length;
    s.images.push({ id: uid(), url: text, name: "图片链接 " + (idx + 1), kind: "url", x: 430 + idx * 42, y: 120 + idx * 34 });
  } else {
    if (s.audios.length >= MAX_AUDIOS) { toast("参考音频最多 " + MAX_AUDIOS + " 段"); return; }
    let name = text;
    try { name = new URL(text).hostname + " · 音频"; } catch { name = "音频链接"; }
    const idx = s.audios.length;
    s.audios.push({ id: uid(), url: text, name: name, kind: "url", x: 430 + idx * 42, y: 560 + idx * 96 });
  }
  invalidateTidySnap(s);
  s.urlText = "";
  s.urlDialogOpen = false;
  persistAssets(s);
  render();
}

function removeImage(id) {
  const s = S();
  invalidateTidySnap(s);
  s.images = s.images.filter(function (im) { return im.id !== id; });
  persistAssets(s);
  render();
}
function removeAudio(id) {
  const s = S();
  invalidateTidySnap(s);
  s.audios = s.audios.filter(function (a) { return a.id !== id; });
  if (s.playing === id) {
    if (s.audioObj) s.audioObj.pause();
    s.playing = null; s.audioObj = null;
  }
  persistAssets(s);
  render();
}

function toggleAudio(id) {
  const s = S();
  const a = s.audios.find(function (x) { return x.id === id; });
  if (!a) return;
  if (s.playing === id) {
    if (s.audioObj) s.audioObj.pause();
    s.playing = null; s.audioObj = null;
  } else {
    if (s.audioObj) s.audioObj.pause();
    const au = new Audio(a.url);
    au.onended = function () { if (s.playing === id) { s.playing = null; patchBars(); } };
    au.play().catch(function () { });
    s.audioObj = au; s.playing = id;
  }
  patchBars();
}
function patchBars() {
  const s = S();
  const bars = app.querySelectorAll("[data-fid^=abars-]");
  bars.forEach(function (el) {
    const id = el.getAttribute("data-fid").slice(6);
    el.className = "uv-bars" + (s.playing === id ? " playing" : "");
  });
}

