// ─────────────────────────────────────────────────────────────
// v6.55（P3）：组卡绑定到描述词。绑定标记直接长在组对象上
// （g.bindPrompt / g.bindPromptOrder），随 groups 整体存取、复制、
// 整理自动带走；素材的 groupId 绑定/解绑一字未动。提交时由
// assembleSubmission 拼装：无绑定时返回值与 v6.54 逐字节一致；
// 有绑定时按主体序（角色先、场景后、按绑定时间）排素材、前置
// <Subject N> 定义行、正文里的组名加注标签；界面上的 s.prompt
// 原文一个字不动，只改发出去的提交体。
// ─────────────────────────────────────────────────────────────
function boundPromptGroups(s) {
  return s.groups.filter(function (g) { return !!g.bindPrompt; }).sort(function (a, b) {
    if (a.kind !== b.kind) return a.kind === "char" ? -1 : 1;
    return (a.bindPromptOrder || 0) - (b.bindPromptOrder || 0);
  });
}
function bindGroupPrompt(gid) {
  const s = S();
  const g = getGroup(s, gid);
  if (!g) return;
  g.bindPrompt = true;
  if (!g.bindPromptOrder) g.bindPromptOrder = Date.now();
  s.menu = null;
  persistState(s);
  render();
  toast("已将「" + g.name + "」绑定到描述词");
}
function unbindGroupPrompt(gid) {
  const s = S();
  const g = getGroup(s, gid);
  if (!g) return;
  delete g.bindPrompt;
  delete g.bindPromptOrder;
  s.menu = null;
  persistState(s);
  render();
  toast("已取消「" + g.name + "」与描述词的绑定");
}
function toggleGroupPrompt(gid) {
  const g = getGroup(S(), gid);
  if (!g) return;
  if (g.bindPrompt) unbindGroupPrompt(gid);
  else bindGroupPrompt(gid);
}
function assembleSubmission(s) {
  const rawPrompt = s.prompt.trim();
  const bound = boundPromptGroups(s);
  if (!bound.length) {
    return { prompt: rawPrompt, images: s.images.slice(), audios: s.audios.slice() };
  }
  const orderedImages = [], orderedAudios = [];
  const subjDefs = [], unmentionedTags = [];
  let annotatedBody = rawPrompt;
  const hasSubjectTag = /<Subject\s+\d+>/i.test(rawPrompt);

  bound.forEach(function (g, idx) {
    const subjTag = "<Subject " + (idx + 1) + ">";
    const picTags = [], audTags = [];
    s.images.forEach(function (im) {
      if (im.groupId === g.id) {
        orderedImages.push(im);
        picTags.push("<Picture " + orderedImages.length + ">");
      }
    });
    s.audios.forEach(function (a) {
      if (a.groupId === g.id) {
        orderedAudios.push(a);
        audTags.push("<Audio " + orderedAudios.length + ">");
      }
    });
    if (!hasSubjectTag && picTags.length) {
      subjDefs.push(subjTag + " (" + g.name + ") is the " + (g.kind === "char" ? "character" : "scene environment") + " in " + picTags.join(", ") + (audTags.length ? " with voice from " + audTags.join(", ") : "") + ".");
      if (annotatedBody.indexOf("@" + g.name) >= 0) {
        annotatedBody = annotatedBody.split("@" + g.name).join(g.name + " (" + subjTag + ")");
      } else if (annotatedBody.indexOf(g.name) >= 0) {
        annotatedBody = annotatedBody.split(g.name).join(g.name + " (" + subjTag + ")");
      } else {
        unmentionedTags.push(subjTag + " (" + g.name + ")");
      }
    }
  });

  // 未绑定的散素材排在已绑主体素材之后，环境参考照常进提交体。
  s.images.forEach(function (im) { if (orderedImages.indexOf(im) < 0) orderedImages.push(im); });
  s.audios.forEach(function (a) { if (orderedAudios.indexOf(a) < 0) orderedAudios.push(a); });

  let finalPrompt = rawPrompt;
  if (!hasSubjectTag && subjDefs.length) {
    const prefix = unmentionedTags.length ? (unmentionedTags.join("、") + "：") : "";
    finalPrompt = subjDefs.join("\n") + "\n\n" + prefix + annotatedBody;
  }
  return { prompt: finalPrompt, images: orderedImages, audios: orderedAudios };
}

