// v6.59：输入防抖保存——每次击键先把状态行标成「未保存…」，停笔
// 400ms 后真正落盘并回读校验，状态行随之变「已保存 · 时间」或明示
// 没存上。保存按钮仍在（双保险，走 persistAll 老路径）。
let keySaveTimer = null;
function keyStatusText(which) {
  const v = which === "token" ? token : dskey;
  if (!v) return "未填写";
  if (keyPersistFailed) return "没存上——这个浏览器没把密钥存下来，请用下方「导出」备份，下次粘贴回来";
  const at = which === "token" ? keySavedAt.token : keySavedAt.dskey;
  if (at) {
    const d = new Date(at);
    const p2 = function (n) { return String(n).padStart(2, "0"); };
    return "已保存 · " + d.getFullYear() + "-" + p2(d.getMonth() + 1) + "-" + p2(d.getDate()) + " " + p2(d.getHours()) + ":" + p2(d.getMinutes());
  }
  return "已保存";
}
function patchKeyStatus(which, dirty) {
  const el = app.querySelector('[data-key-status="' + which + '"]');
  if (!el) return;
  // 同行「清除」钮的可用态跟着值走：对话框打开时该行还是空值渲染
  // 的（清除钮禁用），用户填入后不用重开对话框、清除钮立刻可用。
  const row = el.closest(".uv-key-row");
  const clearBtn = row ? row.querySelector("button") : null;
  if (clearBtn) clearBtn.disabled = !(which === "token" ? token : dskey);
  el.innerHTML = dirty
    ? '<span class="dirty">未保存…</span>'
    : (keyStatusText(which) === "未填写" || (which === "token" ? token : dskey) === ""
      ? "未填写"
      : '<span class="' + (keyPersistFailed ? "dirty" : "ok") + '">' + esc(keyStatusText(which)) + "</span>");
}
function scheduleKeySave(which) {
  patchKeyStatus(which, true);
  if (keySaveTimer !== null) __llClearTimeout(keySaveTimer);
  keySaveTimer = __llSetTimeout(function () {
    keySaveTimer = null;
    persistKeys();
    patchKeyStatus("token", false);
    patchKeyStatus("dskey", false);
  }, 400);
}
function onTokenInput(el) { token = el.value; keyClearArm = ""; scheduleKeySave("token"); }
function onDsInput(el) { dskey = el.value; keyClearArm = ""; scheduleKeySave("dskey"); }
function onUrlInput(el) { const s = S(); s.urlText = el.value; }
