// v6.59：密钥导出/导入兜底——万一某个浏览器环境真存不住（对话框
// 状态行会明示），用户可以把两把钥匙复制出去存好、下次粘贴回来。
// 导出走剪贴板、导入走对话框里的输入框，都只在本机发生。
function exportKeys() {
  const text = JSON.stringify({ flor911Keys: 1, token: token, dskey: dskey });
  const done = function () { toast("已复制，请存到你自己的记事本里（里面是明文密钥，别发给别人）"); };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(done).catch(function () { legacyCopy(text); done(); });
  } else { legacyCopy(text); done(); }
}
function toggleKeyImport() { keyImportOpen = !keyImportOpen; render(); }
function onKeyImportInput(el) { keyImportText = el.value; }
function importKeys() {
  const raw = (keyImportText || "").trim();
  if (!raw) { toast("先把之前导出的内容粘进来"); return; }
  let t = "", d = "";
  try {
    const j = JSON.parse(raw);
    if (j && typeof j === "object") { t = String(j.token || ""); d = String(j.dskey || ""); }
  } catch { }
  if (!t && !d) {
    // 不是导出格式时按纯文本兜底：整段当 autodl Token。
    t = raw;
  }
  if (t) token = t;
  if (d) dskey = d;
  keyImportText = "";
  keyImportOpen = false;
  persistKeys();
  render();
  toast(keyPersistFailed ? "已填入，但这个浏览器没存下来，下次打开可能还要再粘一次" : "已导入并保存");
}
